package slam_test

import (
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"

	root "github.com/lechandonga/lidar-slam-pose-graph-go"
)

// TestRealV1StateLoads uses a state file produced by the PREVIOUS released
// build (v1), checked into testdata/legacy-v1.gob. It is not a hand-built
// struct: the file was generated by running the v1 program's Save over a
// real loop dataset, so it exercises the exact historical wire format.
//
// Regenerate with the v1 source (see docs/multi-session.md §5):
//
//	cd <v1 checkout> && go run ./cmd/genstate ./legacy-v1.gob
func TestRealV1StateLoads(t *testing.T) {
	data, err := os.ReadFile(filepath.Join("testdata", "legacy-v1.gob"))
	if err != nil {
		t.Skipf("legacy v1 fixture missing: %v", err)
	}
	dir := t.TempDir()
	path := filepath.Join(dir, "legacy-v1.gob")
	if err := os.WriteFile(path, data, 0o600); err != nil {
		t.Fatal(err)
	}

	p, err := root.LoadState(path, root.NopLogger())
	if err != nil {
		t.Fatalf("real v1 file must migrate and load, got: %v", err)
	}
	n, e := p.GraphSummary()
	occ := countOccupied(p.MapSnapshot())
	t.Logf("real v1 loaded: nodes=%d edges=%d occupied=%d session=%d",
		n, e, occ, p.Session())
	if n == 0 || occ == 0 {
		t.Fatal("migrated v1 state lost the map/graph")
	}
	if p.Session() != 0 {
		t.Fatalf("v1 must migrate to session 0, got %d", p.Session())
	}

	// Round-trip through the current writer: the migrated state must then
	// load as a normal v2 file and keep its contents.
	path2 := filepath.Join(dir, "resaved.gob")
	if err := p.Save(path2); err != nil {
		t.Fatal(err)
	}
	p2, err := root.LoadState(path2, root.NopLogger())
	if err != nil {
		t.Fatalf("resaved state must load: %v", err)
	}
	n2, e2 := p2.GraphSummary()
	if n2 != n || e2 != e || countOccupied(p2.MapSnapshot()) != occ {
		t.Fatalf("resave changed content: %d/%d/%d vs %d/%d/%d",
			n2, e2, countOccupied(p2.MapSnapshot()), n, e, occ)
	}
	t.Logf("v1->v2 resave stable: nodes=%d edges=%d occupied=%d", n2, e2, occ)
}

// TestErrorKindsDistinguishable confirms a complete-but-old/unsupported file
// is reported as an unsupported VERSION (not corruption), while a truncated
// file is reported as corrupt.
func TestErrorKindsDistinguishable(t *testing.T) {
	dir := t.TempDir()

	// Unsupported (future) version, otherwise a well-formed file.
	future := filepath.Join(dir, "future.gob")
	if err := root.ExportWriteFutureState(future); err != nil {
		t.Fatal(err)
	}
	_, err := root.LoadState(future, root.NopLogger())
	if !errors.Is(err, root.ErrUnsupportedState) {
		t.Fatalf("future version must be ErrUnsupportedState, got %v", err)
	}
	t.Logf("future version rejected distinctly: %v", err)

	// Truncated real v1 file: structurally a v1 label but cut in half, so it
	// must be called corrupt rather than "unsupported version".
	raw, rerr := os.ReadFile(filepath.Join("testdata", "legacy-v1.gob"))
	if rerr == nil {
		trunc := filepath.Join(dir, "trunc-v1.gob")
		if err := os.WriteFile(trunc, raw[:len(raw)/3], 0o600); err != nil {
			t.Fatal(err)
		}
		_, terr := root.LoadState(trunc, root.NopLogger())
		if terr == nil {
			t.Fatal("truncated v1 must fail")
		}
		if errors.Is(terr, root.ErrUnsupportedState) {
			t.Fatalf("truncated v1 must be corrupt, not unsupported: %v", terr)
		}
		if !strings.Contains(terr.Error(), "corrupt") {
			t.Fatalf("truncated v1 error must mention corrupt: %v", terr)
		}
		t.Logf("truncated v1 reported as corrupt (not old version): %v", terr)
	}

	// Plain garbage.
	garbage := filepath.Join(dir, "garbage.gob")
	if err := os.WriteFile(garbage, []byte("this is not a gob file"), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := root.LoadState(garbage, root.NopLogger()); err == nil {
		t.Fatal("garbage must be rejected")
	} else {
		t.Logf("garbage rejected: %v", err)
	}
}
